  "Token saving": "トークン節約",
  "What this host does by itself to spend fewer tokens. None of it restricts which model you choose.": "トークン消費を減らすためにこのホストが自動で行うことです。選べるモデルを制限するものはありません。",
  "Compact automatically": "自動圧縮",
  "A session whose last request filled this share of the model's context window is compacted before the next message. Each session can choose its own value from its context meter.": "直近のリクエストがコンテキストウィンドウのこの割合に達したセッションは、次のメッセージの前に圧縮されます。各セッションはコンテキストメーターから独自の値を選べます。",
  "Short turn context": "ターンコンテキストの短縮",
