  "Compact tool results": "ツール結果の圧縮",
  "Timeline snapshots are summaries unless the agent asks for more, lists are paged, and no result is larger than 32 KiB.": "タイムラインのスナップショットはエージェントが詳細を求めない限り要約で、一覧はページ分割され、結果は 32 KiB を超えません。",
  "Pause a runaway turn": "暴走ターンの一時停止",
