  "A multi-camera source holds only its angles": "マルチカメラのソースには、そのアングルだけが入ります",
  "Turn on 'Audio follows video' to flatten": "フラット化するには「音声を映像に追従」をオンにしてください",
  "No scene changes detected": "シーンの切り替わりは検出されませんでした",
  "Place two clips next to each other to add a transition": "トランジションを追加するには、2 つのクリップを隣り合わせに置いてください",
  "Audio was extracted. Add a crossfade on the audio track.": "音声は抽出済みです。オーディオトラックにクロスフェードを追加してください。",
