  "This build is not signed, so it cannot install an update by itself. A new version is downloaded and verified; open the downloaded file to install it.": "このビルドは署名されていないため、自動でアップデートをインストールできません。新しいバージョンはダウンロードして検証されます。ダウンロードしたファイルを開いてインストールしてください。",
  "This version is kept on this device and opens without a network.": "このバージョンはこのデバイスに保存され、ネットワークなしで開けます。",
