  "{name} is not installed on this host.": "{name} はこのホストにインストールされていません。",
  "{name} on the host, driven over the Agent Client Protocol with its own sign-in and permissions.": "ホスト上の {name}。Agent Client Protocol 経由で、独自のサインインと権限で動作します。",
  "The {name} agent on the host, driven over the Agent Client Protocol.": "ホスト上の {name} エージェント。Agent Client Protocol 経由で動作します。",
