  "Enter the code shown next to {fingerprint}": "{fingerprint} の横に表示されているコードを入力",
  "Name of this device": "このデバイスの名前",
  "On the host, open Devices → Pair a device and copy the link.": "ホストで「デバイス」→「デバイスをペアリング」を開き、リンクをコピーします。",
  "The host proved its identity. A device that is already trusted on that host now shows a six-digit code for this request.": "ホストの身元が確認されました。そのホストで既に信頼されているデバイスに、このリクエスト用の 6 桁のコードが表示されています。",
