  "Delete shot {n}": "ショット {n} を削除",
  "Project “{name}” is moved to the host trash. It can be restored from there for 30 days.": "プロジェクト「{name}」はホストのゴミ箱に移動されます。30 日間はそこから復元できます。",
  "Project “{name}” is restored from the host trash.": "プロジェクト「{name}」はホストのゴミ箱から復元されます。",
  "An empty workflow with only its trigger.": "トリガーだけの空のワークフローです。",
  "Add step “{name}” ({type})": "ステップ「{name}」({type}) を追加",
  "Change step “{name}”": "ステップ「{name}」を変更",
