  "Set the workflow's parameters": "ワークフローのパラメーターを設定",
  "Set the workflow's variables": "ワークフローの変数を設定",
  "Set the workflow's outputs": "ワークフローの出力を設定",
  "Change the workflow's settings": "ワークフローの設定を変更",
  "Rename or describe the workflow": "ワークフローの名前または説明を変更",
  "The character and its reference picture are removed from the film.": "キャラクターとその参照画像が映画から削除されます。",
  "The character and its reference picture are removed from the film. Lines spoken by them that fall back to the narrator: {n}.": "キャラクターとその参照画像が映画から削除されます。ナレーターに戻るこのキャラクターのセリフ: {n} 件。",
  "The scene and its shots ({n}) are removed from the film, and voice lines bound to those shots are unbound.": "シーンとそのショット ({n}) が映画から削除され、それらのショットに結び付いたセリフは切り離されます。",
  "The shot and its image are removed from the film. No voice line is bound to it.": "ショットとその画像が映画から削除されます。結び付いたセリフはありません。",
  "The shot and its image are removed from the film. Voice lines bound to it that are unbound: {n}.": "ショットとその画像が映画から削除されます。切り離されるセリフ: {n} 件。",
  "Answered a hand-back": "差し戻しに回答しました",
  "Submitted a review": "レビューを提出しました",
  "Settled a disagreement in the team": "チーム内の意見の相違を解決しました",
  "Listed the workflows": "ワークフローを一覧しました",
  "Read a workflow": "ワークフローを読みました",
  "Created the workflow “{text}”": "ワークフロー「{text}」を作成しました",
  "Created a workflow": "ワークフローを作成しました",
  "Changed a workflow": "ワークフローを変更しました",
