  "Wrote the scene “{text}”": "シーン「{text}」を書きました",
  "Wrote a scene of the film": "映画のシーンを書きました",
  "Wrote a shot of the film": "映画のショットを書きました",
  "Deleted a character of the film": "映画のキャラクターを削除しました",
