  "Last edited by Film Studio": "最終編集: フィルムスタジオ",
  "Last edited by an automation": "最終編集: オートメーション",
  "A device that is no longer paired": "ペアリングが解除されたデバイス",
  "The agent “{name}”": "エージェント「{name}」",
  "The agent": "エージェント",
  "A workflow run": "ワークフローの実行",
  "An automation": "オートメーション",
  "“Try again” exports the project as it is now, with the edits you made since.": "「もう一度試す」は、その後の編集を含む現在のプロジェクトを書き出します。",
  "The file “{file}” could not be exported: it is not on this device. Wait until it has arrived or replace it, then export again.": "ファイル「{file}」を書き出せませんでした。このデバイスにありません。届くまで待つか別のファイルに置き換えてから、もう一度書き出してください。",
  "{model} cannot speak in the voice of a sample. Choose a voice model that can in Settings ▸ Model routing.": "{model} はサンプルの声で話せません。設定 ▸ モデルルーティングで、それができる音声モデルを選んでください。",
  "{model} takes no accent: it speaks the way its voice does.": "{model} はアクセントを指定できません。選んだ声のままで話します。",
