  "Tailscale is how your phone reaches this computer from anywhere, with no server in between. Sign in to Tailscale on this computer, then pair your phone.": "Tailscale を使うと、中継サーバーなしでスマートフォンからどこからでもこのコンピューターに接続できます。このコンピューターで Tailscale にサインインしてから、スマートフォンをペアリングしてください。",
